// Shape the Trellis publish payload into YouTube-ready fields.
const b = $json.body || $json;
const m = b.metadata || {};
const chapters = Array.isArray(m.chapters) ? m.chapters : [];
const chapterLines = chapters.map(c => `${c.time || '0:00'} ${c.title || ''}`.trim()).filter(Boolean).join('\n');
const hashtags = Array.isArray(m.hashtags) ? m.hashtags.join(' ') : '';
const descParts = [
  m.description || '',
  chapterLines ? '\n\nChapters:\n' + chapterLines : '',
  hashtags ? '\n\n' + hashtags : '',
];
const description = descParts.join('').trim().slice(0, 4900); // YT desc limit ~5000
const tags = Array.isArray(m.tags) ? m.tags.join(',').slice(0, 450) : ''; // YT tags total ~500
return { json: {
  publication_id: b.publication_id,
  episode_id: b.episode_id,
  video_url: b.video_url,
  title: (m.title || 'Untitled Episode').slice(0, 95), // YT title max 100
  description,
  tags,
} };

// Pull the YouTube video id out of the upload response regardless of shape
// (top-level id / id.videoId / snippet.resourceId.videoId), with a last-resort
// scan for an 11-char YouTube-id-shaped token.
const y = $json || {};
let id = (y.id && typeof y.id === 'object') ? y.id.videoId : y.id;
id = id || y?.snippet?.resourceId?.videoId || y.videoId;
if (!id) { const m = JSON.stringify(y).match(/"([A-Za-z0-9_-]{11})"/); id = m ? m[1] : null; }
return { json: { video_id: id, youtube_url: id ? ('https://youtu.be/' + id) : null } };
